import { defineProperties } from "figma:react";

export default function AnalogClock({
  updateInterval = 1000,
  secondHandColor = "red",
  minuteHandColor = "black",
  hourHandColor = "black",
}) {
  const [time, setTime] = useState({ hours: 0, minutes: 0, seconds: 0 });

  useEffect(() => {
    const updateClock = () => {
      // Get London's local time using en-GB format
      const londonTimeString = new Date().toLocaleTimeString("en-GB", {
        timeZone: "Europe/London",
        hour12: false
      });
      const [hoursStr, minutesStr, secondsStr] = londonTimeString.split(":");
      setTime({
        hours: parseInt(hoursStr, 10),
        minutes: parseInt(minutesStr, 10),
        seconds: parseInt(secondsStr, 10)
      });
    };

    updateClock();
    const timerId = setInterval(updateClock, updateInterval);
    return () => clearInterval(timerId);
  }, [updateInterval]);

  return (
    <div className="analog-clock-container">
      {/* Clock Face Rendering */}
    </div>
  );
}`,Ef=[{id:"msg-1",role:"user",text:"Hey Flippy! Write me a script for building an Analag Clock."},{id:"msg-2",role:"agent",text:"Sure. Let me spawn an agent which will write the required code for you analogue clock, which language do you prefer? and also enter a name for the agent as well."},{id:"msg-3",role:"user",text:'Give me the code in TypeScript and name the agent as "bob"'}],Pf={call_id:"agent_bob_01",name:"bob",role:"TypeScript Generator",tool_name:"generate_code",arguments:{language:"TypeScript",component:"AnalogClock"},epoch:1,status:"working",thought:"Compiling London timezone-aware analogue clock component with custom hand colors..."},zf={title:"AnalogClock.tsx",language:"typescript",content:Cf,author:"bob",description:"Hi, I am bob. Here is the code in typescript for your Analogue Clock interface."},Rf=`
class PCMCapture extends AudioWorkletProcessor {
  constructor() {
    super();
    this.ratio = sampleRate / 16000;   // input samples per output sample (1 when the context runs at 16 kHz)
    this.pos = 1;                       // read position within [prev, ...block]
    this.prev = 0;
    this.frame = new Int16Array(1600);
    this.filled = 0;
  }
  process(inputs) {
    const ch = inputs[0] && inputs[0][0];
    if (!ch) return true;
    const buf = new Float32Array(ch.length + 1);
    buf[0] = this.prev;
    buf.set(ch, 1);
    let p = this.pos;
    while (p < buf.length - 1) {
      const i = Math.floor(p);
      const f = p - i;
      const v = Math.max(-1, Math.min(1, buf[i] * (1 - f) + buf[i + 1] * f));
      this.frame[this.filled++] = v < 0 ? v * 32768 : v * 32767;
      if (this.filled === this.frame.length) {
        this.port.postMessage(this.frame.buffer, [this.frame.buffer]);
        this.frame = new Int16Array(1600);
        this.filled = 0;
      }
      p += this.ratio;
    }
    this.pos = p - (buf.length - 1);
    this.prev = ch[ch.length - 1];
    return true;
  }
}
registerProcessor('pcm-capture', PCMCapture);
